#include <stdio.h>

/* teste do desafio o-gritador-biblioteca — counter_protocol (03-tdd 3.9.3).
   O primeiro cenario e o mesmo da aula anterior (ana -> ANA): a saida nao
   muda, o caminho muda. O segundo cenario e o que SEPARA os dois caminhos:
   bola7 tem um digito, e menos 32 estragaria o 7 enquanto o toupper o
   devolve intacto. Quem DIGITA e o teste (fopen/fprintf + freopen do
   stdin); a captura do stdout acontece dentro do proprio cenario
   (freopen + fflush, sem fclose no stdout). */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void oGritadorBiblioteca(void);

SM_TEST(a_palavra_ana_gritada) {
    FILE *digitado = fopen("sm_entrada_1.tmp", "w");
    fprintf(digitado, "ana\n");
    fclose(digitado);
    freopen("sm_entrada_1.tmp", "r", stdin);

    freopen("sm_saida_1.tmp", "w", stdout);
    oGritadorBiblioteca();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("ana gritado", linha, "ANA\n",
              "a saida e a mesma da aula anterior: as tres letras em maiuscula");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida e so a palavra gritada: nenhuma linha extra e aceita");
    fclose(f);
}

SM_TEST(o_digito_sai_intacto) {
    FILE *digitado = fopen("sm_entrada_2.tmp", "w");
    fprintf(digitado, "bola7\n");
    fclose(digitado);
    freopen("sm_entrada_2.tmp", "r", stdin);

    freopen("sm_saida_2.tmp", "w", stdout);
    oGritadorBiblioteca();
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
