#include <stdio.h>
#include <ctype.h>

void oGritadorBiblioteca(void) {
    char palavra[50] = "";
    scanf("%49s", palavra);
    for (int i = 0; palavra[i] != '\0'; i++) {
        palavra[i] = toupper(palavra[i]);
    }
    printf("%s\n", palavra);
}
